def safe_reason(error):
    code=str(error)
    if type(error)is ReadDenied:return code
    if re.fullmatch('[A-Z][A-Z0-9_]{0,159}',code):
        for source in CANDIDATE_SOURCES.values():
            raw=base64.b64decode(source['body'],validate=True)
            require(hashlib.sha256(raw).hexdigest()==source['sha256'],'CANDIDATE_DIAGNOSTIC_SOURCE_DRIFT')
            if any(isinstance(n,ast.Constant)and type(n.value)is str and n.value==code for n in ast.walk(ast.parse(raw))):return code
    return type(error).__name__

def candidate_compiler():
    package=types.ModuleType('_ouf_bridge_proposal');package.__path__=[];sys.modules[package.__name__]=package;modules={}
    for name,item in CANDIDATE_SOURCES.items():
        raw=base64.b64decode(item['body'],validate=True);require(hashlib.sha256(raw).hexdigest()==item['sha256'],'CANDIDATE_COMPILER_SOURCE_DRIFT')
        tree=ast.parse(raw)
        if name=='gated_creation_plan':
            tree.body=[n for n in tree.body if isinstance(n,ast.Assign)and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)and n.targets[0].id in('GATE','ENTRY')]
            require(len(tree.body)==2,'EXACT_SIGNED_GATE_CONSTANTS_REQUIRED')
        for node in ast.walk(tree):
            if isinstance(node,ast.ImportFrom)and node.module in CANDIDATE_SOURCES:node.module=package.__name__+'.'+node.module
        module=types.ModuleType(package.__name__+'.'+name);module.__package__=package.__name__
        sys.modules[module.__name__]=module;setattr(package,name,module)
        exec(compile(tree,'<verified-bridge-proposal:'+name+'>','exec'),module.__dict__);modules[name]=module
    return modules['compile_file_only_frame_policy'],modules['file_only_profile']

def bridge_proposal(prepared,native,oci,runtime):
    compiler,profiles=candidate_compiler();registry=prepared['registry'];request=registry['creationRequest'];recipe=registry['nodeRecipe']
    before=encoded((request,recipe));generation=proc_generation(native['State']['Pid'])
