    require(type(sandbox)is str and str(Path(sandbox).parent)==context['networkNamespaceParent'],'EXACT_RETAINED_SANDBOX_PARENT_REQUIRED')
    require(Path(sandbox).stat().st_ino==generation['networkNamespaceInode'],'KERNEL_DOCKER_NAMESPACE_BINDING_REQUIRED')
    require(context.pop('rootfsLayout',None)=='docker-containerd-overlayfs-v1','EXACT_APPROVED_ROOTFS_LAYOUT_REQUIRED')
    require(runtime['bundle']==context['bundleParent']+'/'+CID,'EXACT_APPROVED_BUNDLE_REQUIRED')
    context.update(containerId=CID,networkNamespaceName=compiler.private_bridge_namespace_name(request),
        rootfsPath=context['storageParent']+'/rootfs/overlayfs/'+CID)
    template,launch=compiler.recompile_bridge_proposal(recipe['template'],recipe['launch'],request)
    profile=profiles.FileOnlyProfile(request,registry['configtree'])
    policy=compiler.compile_policy(template,launch,context,execution_profile=profile,
        renewable_token=recipe['renewableToken'],delegation_key_metadata_hash=recipe['delegationKeyMetadataHash'],
        proposal_receipt_key=recipe['proposalReceiptKey'])
    old_env=compiler.environment(recipe['template']['expectedOci']['process']['env'])
    # Materialize only the documented Docker HOSTNAME slot for comparison.
    old_env['HOSTNAME']=CID[:12];native_env=compiler.environment(oci['process']['env'])
    matches=digest(policy['expectedOci'])==digest(oci)
    def names(values):return [name if re.fullmatch('[A-Z_][A-Z0-9_]{0,127}',name)else'[redacted-name]'for name in sorted(values)][:64]
    emit('BRIDGE_PROPOSAL_COMPARISON',candidateSourceCommit=CANDIDATE_COMMIT,
        sameEnvironmentNames=set(old_env)==set(native_env),sameEnvironmentValues=old_env==native_env,
        missingEnvironmentNames=names(set(old_env)-set(native_env)),unexpectedEnvironmentNames=names(set(native_env)-set(old_env)),
        changedEnvironmentNames=names(name for name in set(old_env)&set(native_env)if old_env[name]!=native_env[name]),
        environmentValuesPrinted=False,environmentValueHashesPrinted=False,
        candidateExactEnvironmentOrder=policy['expectedOci']['process']['env']==oci['process']['env'],
        candidateExactFullOci=matches,candidatePrivateNetworkNamespacePathAbsent=True,
        kernelSandboxNamespaceMatched=True,originalSignedCreationRequestPreserved=True,
        expectedOciDerivedFromObservedOci=False,privateValuesPrinted=False,signatureIssued=False,applyAuthorized=False)
    if not matches:emit('CANDIDATE_OCI_DIFFERENCE',**oci_difference(policy['expectedOci'],oci))
    require(encoded((request,recipe))==before and proc_generation(native['State']['Pid'])==generation,'BRIDGE_PROPOSAL_INPUT_OR_GENERATION_DRIFT')
    return policy if matches else None

