CI_ENTRIES_ZLIB=''

def replay_entry_stream(rows):
    h=hashlib.sha256(b'OUF-ROOTFS-SEAL\x00V1\x00');seen=set();total=0
    for item in rows:
        require(type(item)is dict and type(item.get('path'))is str and item['path']not in seen,'UNIQUE_CI_IMAGE_ENTRIES_REQUIRED')
        seen.add(item['path']);raw=encoded(item);h.update(len(raw).to_bytes(4,'big'));h.update(raw)
        if item['kind']=='file':total+=item['size']
    return {'schema':'ouf.semantic-rootfs-seal.v1','sha256':h.hexdigest(),'entries':len(rows),'bytes':total}

def ci_image_entries(expected_seal):
    raw=base64.b64decode(CI_ENTRIES_ZLIB,validate=True);stream=zlib.decompressobj()
    data=stream.decompress(raw,2097153)
    require(len(data)<=2097152 and stream.eof and not stream.unused_data and not stream.unconsumed_tail,'BOUNDED_CI_IMAGE_MANIFEST_REQUIRED')
    require(hashlib.sha256(data).hexdigest()==CI_ENTRIES_SHA,'CI_IMAGE_MANIFEST_HASH_DRIFT')
    doc=json.loads(data,object_pairs_hook=unique);summary=doc['summary'];rows=doc['entries']
    require(type(rows)is list and 1<=len(rows)<=100000 and summary['sourceCommit']=='eccef11a97367f20e278db40b9ed6f45dd980c37'
        and summary['configurationImageId']=='sha256:29e32c1487b5ba29d6d29ec04f7daa3baeb1e30f392a46c838eef01493d60489'
        and summary['partArtifactSha256']=='5d28e55ca5541efadec4b93a6396c8f84d21e6db92766b785b1cd8c3fd10db09'
        and summary['qualifiedSealMatches']is True and summary['stableDoubleSeal']is True
        and summary['javaStarted']is False and summary['qualifiedRootfsSeal']==summary['observedRootfsSeal']==expected_seal
        and replay_entry_stream(rows)==expected_seal,'CI_ENTRIES_MUST_REPRODUCE_RETAINED_QUALIFIED_SEAL')
    return {item['path']:item for item in rows}

def rootfs_differences(expected,observed,policy,maximum=40):
    counts={};samples=[];different=0;targets=[b['target'].lstrip('/')for b in [*policy['sources'],policy['configtree'],policy['renewableToken']]]
    for path in sorted(set(expected)|set(observed)):
        left=expected.get(path);right=observed.get(path)
        if left==right:continue
        different+=1
        if left is None:fields=['UNEXPECTED_ENTRY']
        elif right is None:fields=['MISSING_ENTRY']
        else:fields=[field for field in sorted(set(left)|set(right))if field!='path'and left.get(field)!=right.get(field)]
        allowed={'kind','mode','uid','gid','links','size','sha256','target','xattrs','UNEXPECTED_ENTRY','MISSING_ENTRY'}
        require(set(fields)<=allowed,'CLOSED_ROOTFS_DIFFERENCE_FIELDS_REQUIRED')
        for field in fields:counts[field]=counts.get(field,0)+1
        if len(samples)>=maximum:continue
        shown=path if len(path)<=512 and re.fullmatch('[A-Za-z0-9_./+@=,~%-]*',path)else'[redacted-image-path]'
        sample={'imagePath':shown or'.','differentFields':fields,'declaredPrivateMountPathOrAncestor':bool(path)and any(t==path or t.startswith(path+'/')for t in targets)}
        for label,item in [('expected',left),('observed',right)]:
            if item is not None:sample[label]={k:item[k]for k in('kind','mode','uid','gid','links','size')if k in item}
        samples.append(sample)
    return dict(differentEntryCount=different,fieldCounts=counts,samples=samples,samplesTruncated=different>maximum,
        fileContentsPrinted=False,contentHashesPrinted=False,xattrValuesPrinted=False,symlinkTargetsPrinted=False,
        acceptanceGranted=False,signatureIssued=False)

def host_image_mount_guard(root):
    with open('/proc/self/mountinfo','rb')as stream:raw=stream.read(1048577)
    require(len(raw)<=1048576,'BOUNDED_HOST_MOUNT_METADATA_REQUIRED')
    for line in raw.decode().splitlines():
        value=line.split(' - ',1)[0].split()[4]
        point=Path(re.sub(r'\\([0-7]{3})',lambda m:chr(int(m.group(1),8)),value))
        require(point==root or not point.is_relative_to(root),'PRIVATE_SUBMOUNT_IN_IMAGE_SCAN_DENIED')

def image_rootfs_preflight(policy,prepared,native,sources):
    """Run the frozen read-only sealer on image view, never secret bind views."""
    root=Path(policy['expectedOci']['root']['path']);recipe=prepared['registry']['nodeRecipe'];before=proc_generation(native['State']['Pid'])
    expected=ci_image_entries(recipe['expectedRootfsSeal']);records={}
    emit('CI_BASELINE_MANIFEST',runId=CI_RUN,sourceCommit=CI_SOURCE,entries=len(expected),exactRetainedQualifiedSealReproduced=True,expectedEntriesDerivedFromTarget=False)
    def capture(item):
        require(item['path']not in records,'UNIQUE_IMAGE_ENTRY_STREAM_REQUIRED');records[item['path']]=item
        return encoded(item)
    host_image_mount_guard(root)
    # The host-side image view must not expose any of the four private mounts.
    for binding in [*policy['sources'],policy['configtree'],policy['renewableToken']]:
        view=root/binding['target'].lstrip('/')
        try:a=view.stat();b=Path(binding['source']).stat()
        except FileNotFoundError:continue
        require((a.st_dev,a.st_ino)!=(b.st_dev,b.st_ino),'PRIVATE_BIND_VISIBLE_IN_IMAGE_SCAN_DENIED')
    functions={'tools.semantic_provider_deployment_authentication':{'attributes','ancestors'},'tools.semantic_provider_node_observation':{'rootfs_seal'}}
    ns=dict(require=require,hashlib=hashlib,os=os,stat=stat,Path=Path,encoded=capture)
    for name,wanted in functions.items():
        raw=base64.b64decode(sources[name],validate=True);require(hashlib.sha256(raw).hexdigest()==SEAL_SOURCE_PINS[name],'FROZEN_IMAGE_SEAL_SOURCE_DRIFT')
        tree=ast.parse(raw);tree.body=[n for n in tree.body if isinstance(n,ast.FunctionDef)and n.name in wanted]
        require(len(tree.body)==len(wanted),'EXACT_READ_ONLY_IMAGE_SEAL_FUNCTIONS_REQUIRED')
        exec(compile(tree,'<verified-image-seal:'+name+'>','exec'),ns)
    import time
    class Budget:
        def __init__(self):self.until=time.monotonic()+180
        def check(self):require(time.monotonic()<self.until,'FINITE_READBACK_IMAGE_SCAN_TIMEOUT')
    emit('QUALIFIED_IMAGE_ROOTFS_BEGIN',maximumSeconds=180,imageFilesRead=True,credentialOrTokenFilesRead=False)
    observed=ns['rootfs_seal'](root,recipe['observationConfiguration']['rootfsLimits'],Budget())
    require(proc_generation(native['State']['Pid'])==before,'IMAGE_SCAN_PROCESS_GENERATION_DRIFT')
    require(replay_entry_stream(list(records.values()))==observed,'UNCHANGED_NATIVE_ENTRY_STREAM_REQUIRED')
    emit('ROOTFS_ENTRY_DIFFERENCES',**rootfs_differences(expected,records,policy))
    emit('QUALIFIED_IMAGE_ROOTFS',sameAsQualifiedImageSeal=observed==recipe['expectedRootfsSeal'],
        entries=observed['entries'],bytes=observed['bytes'],expectedEntries=recipe['expectedRootfsSeal']['entries'],expectedBytes=recipe['expectedRootfsSeal']['bytes'],imageFilesRead=True,
        credentialOrTokenFilesRead=False,signatureIssued=False,acceptanceGranted=False)
    return observed==recipe['expectedRootfsSeal']

def main():
    require(os.geteuid()==0,'ROOT_READ_ACCESS_REQUIRED');signal.alarm(240)
    emit('BEGIN',serviceMutations=0,databaseMutations=0,grantRequests=0,iamCalls=0,credentialOrTokenFilesRead=False)
    review=read(CONTEXT/'review.json');require(digest(review)==REVIEW and review['sourceClosure']['declaration']['sourceCommit']==SOURCE,'EXACT_FAILED_REVIEW_REQUIRED')
    authority=read(CONTEXT/'authority.json',131072,AUTHORITY);require(all(authority[k]==v for k,v in review['scopes'].items()),'SIGNED_SCOPE_DRIFT')
    process=review['scopes']['finiteActionProcess'];require(process['unit']==UNIT and process['authorityDirectory']==str(CONTEXT),'EXACT_FAILED_PROCESS_REQUIRED')
    bundle=read(process['bundle']['path'],8388608,process['bundle']['sha256']);p=bundle['prepared']
    require(bundle['declaration']==review['sourceClosure']['declaration']and digest(p)==review['privateInputHashes']['preparedInputs'],'BUNDLE_OR_INPUT_DRIFT')
    status=read(CONTEXT/'delivery-status.json',16384);require(status['authorityHash']==AUTHORITY,'STATUS_AUTHORITY_DRIFT')
    require(status.get('phase')=='PAUSED_REQUIRES_RECONCILIATION'and status.get('reason')=='ValueError','EXACT_RETAINED_FAILURE_REQUIRED')
    emit('RETAINED_STATUS',phase=status['phase'],reason=status.get('reason'),runtimeAuthorityIssuedByReader=False)
    r=subprocess.run(['/usr/bin/systemctl','show',UNIT,'--property=ActiveState,SubState,MainPID,Job'],stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=10)
    require(r.returncode==0 and len(r.stdout)<=8192,'PROCESS_READ_UNAVAILABLE');rows=dict(l.split('=',1)for l in r.stdout.decode().splitlines()if'='in l)
    require(rows.get('ActiveState')in('inactive','failed')and rows.get('MainPID')=='0'and rows.get('Job')=='','DELIVERY_MUST_BE_STOPPED_FOR_READBACK')
    emit('PROCESS',stopped=True)
    reservation=read(CONTEXT.parent/'chatbot-file-cohort-postgrant-7db9ea82ed6fbbdc88cfdbd8e7315404e6c958e841731d1d12b22482f8fa8f30.claim.json',8192)
    emit('CONTINUATION_RESERVATION',authorityMatches=reservation.get('authorityHash')==AUTHORITY,**projection(reservation))
    paths=p['registry']['directoryPlan'];transition=read(Path(paths['transition'])/'recovery.json')
    phase_names={'STOP_REVOKE_OLD_LEASE','QUIESCE_PRODUCERS','FENCED_BACKUP','RELEASE_OLD_ENDPOINT','CREATE_REPLACEMENT','STAGE_PAUSED_REPLACEMENT','ATTEST_NEW_OCI_PEER','ADMIT_MIGRATION','START_REPLACEMENT','VERIFY_APPLICATION','RELEASE_PRODUCERS'}
    require(all(x.get('phase')in phase_names and x.get('state')in('APPLIED','IN_FLIGHT','NO_EFFECT','UNKNOWN')for x in transition['effects']),'SAFE_PHASE_PROJECTION_REQUIRED')
    emit('REGISTRY_TRANSITION',**projection(transition),recordHash=digest(transition),phases=[{'phase':x['phase'],'state':x['state']}for x in transition['effects']])
    owner=Path(review['scopes']['policyTokenOwnerInstallation']['journalPath'])
    for name in ('recovery.json','owner-session.json','owner-admission.json'):
        attempt('WORKER_'+name,lambda name=name:emit('WORKER_'+name,recordHash=digest(read(owner/name)),**projection(read(owner/name))))
    for name in ('containers','databases','gateway','authorization'):
        attempt('LATER_'+name,lambda name=name:emit('LATER_'+name,**projection(read(Path(process['directoryPlan'][name])/'recovery.json'))))
    native=inspect(p['engine']);state=native['State'];pid=state['Pid']
    require(state.get('Status')in('created','running','paused','restarting','removing','exited','dead'),'SAFE_ENGINE_STATUS_REQUIRED')
    emit('REGISTRY_NATIVE',running=state['Running'],paused=state['Paused'],status=state['Status'],restartCount=native['RestartCount'],pid=pid)
    require(state['Running']is True and state['Paused']is True and type(pid)is int and pid>1,'PAUSED_GENERATION_REQUIRED')
    recipe=p['registry']['nodeRecipe'];runtime=command(recipe['observationConfiguration']['runtimeBinding'],['--root',recipe['runtimeRoot'],'state',CID])
    require(runtime['id']==CID and runtime['pid']==pid and runtime['status']=='paused','EXACT_RUNC_PAUSED_GENERATION_REQUIRED')
    cfg_path=Path(runtime['bundle'])/'config.json'
    require(cfg_path.parent.parent==Path(recipe['dockerContext']['bundleParent']),'APPROVED_BUNDLE_PARENT_REQUIRED')
    # Runtime config is root-controlled but Docker may use0644. It contains no credential file bodies.
    raw=runtime_config(cfg_path);oci=json.loads(raw);policy=read(Path(paths['node'])/'frame-policy.json',131072)
    emit('RETAINED_FRAME_POLICY',exactOciMatches=digest(oci)==digest(policy['expectedOci']),signatureClaimPresent=(Path(paths['node'])/'attestation-issuance-claim.json').exists(),privateValuesPrinted=False)
    attempt('OCI_COMPARISON',lambda:original_oci_gate(oci,policy,bundle['sources']))
    attempt('MOUNTS',lambda:mount_projection(native,policy))
    attempt('NETWORK',lambda:network_probe(p,native,oci,runtime['bundle'],bundle['sources']))
    candidate=attempt('BRIDGE_PROPOSAL',lambda:bridge_proposal(p,native,oci,runtime))
    seal_result=None
    if candidate is not None:seal_result=attempt('IMAGE_ROOTFS',lambda:image_rootfs_preflight(candidate,p,native,bundle['sources']))
    require(inspect(p['engine'])==native and runtime_config(cfg_path)==raw,'NATIVE_READBACK_DRIFT')
    emit('END',complete=not ERRORS,unavailableChecks=ERRORS,serviceMutations=0,databaseMutations=0,grantRequests=0,
        credentialOrTokenFilesRead=False,authorityRenewed=False,chatbotEndToEndProven=False,
        rootfsSealCheckPerformed=seal_result is not None,frameByteContentChecksPerformed=False,attestationAccepted=False,
        candidateExactFullOci=candidate is not None,candidateImageRootfsMatches=seal_result)

if __name__=='__main__':
    try:main()
    except Exception as e:
        reason=safe_reason(e)
        emit('STOP',reason=reason if re.fullmatch('[A-Za-z_][A-Za-z0-9_]{0,100}',reason)else'UNCLASSIFIED',exceptionMessagePrinted=False,locations=safe_locations(e))
        sys.exit(2)
